entries[233984] = { ["name"] = "Arcane Megabomb", ["text"] = "Requires Level 60\nUse: Drains 1075 to 1525 mana from those in the blast radius and does 50% of the mana drained in damage to the target. Also Silences targets in the blast for 5 sec. (1 Min Cooldown)" }
entries[233985] = { ["name"] = "The Fumigator", ["text"] = "Requires Level 60\nUse: Explodes when triggered dealing 650 to 950 Fire damage to all enemies nearby and 475 to 725 damage to you. Deals extra damage to Silithid creatures in Silithus. (5 Min Cooldown)" }
entries[233986] = { ["name"] = "Obsidian Bomb", ["text"] = "Requires Level 60\nUse: Inflicts 530 to 670 Fire damage in a 5 yard radius. (1 Min Cooldown)" }
entries[233987] = { ["name"] = "G00 DV-1B3 Generator", ["text"] = "Binds when picked up\nUnique\nRequires Level 60\nUse: Unfolds into a G00 DV-1B3 Generator that can repair damaged items and purchase unwanted goods. After 10 min its internal motor fails and it must recover. (4 Hrs Cooldown)" }
entries[233988] = { ["name"] = "Tuned Force Reactive Disk", ["text"] = "Binds when equipped\nOff Hand Shield\n2822 Armor\n52 Block\n+20 Stamina\nDurability 120 / 120\nRequires Level 60\nEquip: Increased Defense +7.\nEquip: When the shield blocks it releases an electrical charge that damages all nearby enemies. (1s cooldown)\nUse: Charge up the energy within the shield for 3 sec to deal 450 to 750 Nature damage to all nearby enemies. After use, the shield needs 10 sec to recharge. (2 Min Cooldown)" }
entries[233990] = { ["name"] = "Speedstone", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 2%.\nEquip: Increases your attack speed by 2%." }
entries[233991] = { ["name"] = "Tear of the Dreamer", ["text"] = "Binds when equipped\nUnique-Equipped: Crystallized Tear (1)\nTrinket\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Increases damage and healing done by magical spells and effects by up to 46." }
entries[233992] = { ["name"] = "Lodestone of Retaliation", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+23 Stamina\nRequires Level 60\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%.\nEquip: Increased Defense +11.\nEquip: When struck in combat inflicts 80 Nature damage to the attacker. Causes twice as much threat as damage dealt." }
entries[233993] = { ["name"] = "Enchanted Stopwatch", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\nRequires Level 60\nUse: Increases run speed by 40% for 10 sec. (2 Min Cooldown)" }
entries[233994] = { ["name"] = "Ruby-Encrusted Broach", ["text"] = "Binds when equipped\nUnique-Equipped: Jeweled Healing Focus (1)\nTrinket\n+18 Intellect\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases healing done by up to 68 and damage done by up to 23 for all magical spells and effects." }
entries[233995] = { ["name"] = "Scroll: Wrath of the Swarm", ["text"] = "Binds when picked up\nRequires Level 60\nRequires Enchanting (300)\nUse: Read from the scroll, evoking the Wrath of the Swarm, empowering your raid to deal up to 40 increased damage and healing with spells, and increasing attack power by 40 for 1 hour. (1 Min Cooldown)" }
entries[233996] = { ["name"] = "Enchanted Repellent", ["text"] = "Requires Level 60\nUse: While applied to target weapon or shield it increases spell damage by up to 45 and increases Spell Critical chance by 1% . Lasts for 30 minutes.\n5 Charges" }
entries[233997] = { ["name"] = "Formula: Enchant Chest - Living Stats", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nUse: Teaches you how to permanently enchant a piece of chest armor to increase all stats by 4, and Nature Resistance by 15." }
entries[233998] = { ["name"] = "Formula: Enchant Gloves - Holy Power", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nUse: Teaches you how to permanently enchant gloves to increase the holy damage done by spells and abilities by 20." }
entries[233999] = { ["name"] = "Formula: Enchant Gloves - Arcane Power", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nUse: Teaches you how to permanently enchant gloves to increase the arcane damage done by spells and abilities by 20." }
