entries[234198] = { ["name"] = "Signet Ring of the Bronze Dragonflight", ["text"] = "Binds when picked up\nUnique-Equipped: Signet Ring of the Bronze Dragonflight (1)\nFinger\n+18 Agility\n+8 Stamina\nRequires Level 60\nRequiresBrood of Nozdormu\n- Neutral\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Gives you 1% chance per piece of Timeworn armor equipped to get an extra attack on melee or ranged hit. (Proc chance: 8%, 200ms cooldown)\n\"The Path of the Conqueror\"" }
