entries[234220] = { ["name"] = "Plans: Razorspike Headcage", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresArmorsmith\nUse: Teaches you how to make Razorspike Headcage.\nRazorspike Headcage\nBinds when equipped\nHead Plate\n722 Armor\n+14 Strength\n+40 Stamina\nDurability 100 / 100\nRequires Level 60\nEquip: When struck in combat inflicts 100 Nature damage to the attacker. Causes twice as much threat as damage dealt.\nEquip: Increased Defense +9.\nRequires Arcanite Bar (15), Obsidian-Infused Thorium Bar (3), Enchanted Leather (4), Wicked Claw (10), Monstrous Silithid Chitin (4)" }
entries[234221] = { ["name"] = "Plans: Razorspike Shoulderplates", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresArmorsmith\nUse: Teaches you how to make Razorspike Shoulderplates.\nRazorspike Shoulderplates\nBinds when equipped\nShoulder Plate\n667 Armor\n+11 Strength\n+29 Stamina\nDurability 100 / 100\nRequires Level 60\nEquip: When struck in combat inflicts 80 Nature damage to the attacker. Causes twice as much threat as damage dealt.\nEquip: Increased Defense +7.\nRequires Arcanite Bar (15), Obsidian-Infused Thorium Bar (3), Enchanted Leather (4), Wicked Claw (10), Monstrous Silithid Chitin (4)" }
entries[234222] = { ["name"] = "Plans: Razorspike Battleplate", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresArmorsmith\nUse: Teaches you how to make Razorspike Battleplate.\nRazorspike Battleplate\nBinds when equipped\nChest Plate\n889 Armor\n+12 Strength\n+40 Stamina\nDurability 165 / 165\nRequires Level 60\nEquip: When struck in combat inflicts 100 Nature damage to the attacker. Causes twice as much threat as damage dealt.\nEquip: Increased Defense +10.\nRequires Arcanite Bar (20), Obsidian-Infused Thorium Bar (4), Enchanted Leather (4), Wicked Claw (10), Monstrous Silithid Chitin (8)" }
entries[234223] = { ["name"] = "Plans: Obsidian Reaver", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresMaster Axesmith\nUse: Teaches you how to make Obsidian Reaver.\nObsidian Reaver\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)\nTwo-Hand Axe\n203 - 340 Damage Speed 3.70\n(73.38 damage per second)\n+40 Strength\n+30 Stamina\nDurability 120 / 120\nRequires Level 60\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)\nRequires Arcanite Bar (40), Obsidian-Infused Thorium Bar (10), Enchanted Leather (8), Obsidian Grinding Stone (6), Alabaster Idol (4), Idol of War (2)" }
entries[234224] = { ["name"] = "Plans: Obsidian Champion", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresMaster Swordsmith\nUse: Teaches you how to make Obsidian Champion.\nObsidian Champion\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)\nTwo-Hand Sword\n117 - 176 Damage Speed 2.00\n(73.25 damage per second)\nDurability 120 / 120\nRequires Level 60\nChance on hit: Heal self for 270 to 450 and Increases Strength by 120 for 30 sec.\nChance on hit: Increases damage done by 20 and attack speed by 5% for 15 sec.\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)\nRequires Arcanite Bar (40), Obsidian-Infused Thorium Bar (10), Enchanted Leather (8), Obsidian Grinding Stone (6), Vermillion Idol (4), Idol of Life (2)" }
entries[234225] = { ["name"] = "Plans: Obsidian Destroyer", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresMaster Hammersmith\nUse: Teaches you how to make Obsidian Destroyer.\nObsidian Destroyer\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)\nTwo-Hand Mace\n117 - 176 Damage Speed 2.00\n(73.25 damage per second)\n+40 Strength\nDurability 120 / 120\nRequires Level 60\nEquip: +260 Attack Power in Cat, Bear, and Dire Bear forms only.\nChance on hit: Stuns target for 3 sec.\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)\nRequires Arcanite Bar (40), Obsidian-Infused Thorium Bar (10), Obsidian Grinding Stone (8), Alabaster Idol (4), Vermillion Idol (4), Idol of Night (2)" }
entries[234226] = { ["name"] = "Plans: Obsidian Stormhammer", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresMaster Hammersmith\nUse: Teaches you how to make Obsidian Stormhammer.\nObsidian Stormhammer\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)\nMain Hand Mace\n49 - 117 Damage Speed 2.00\n(41.50 damage per second)\n+10 Stamina\n+8 Intellect\nDurability 105 / 105\nRequires Level 60\nChance on hit: Blasts up to 3 targets for 105 to 145 Nature damage.\nEquip: Increases damage and healing done by magical spells and effects by up to 60.\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)\nRequires Arcanite Bar (30), Obsidian-Infused Thorium Bar (8), Enchanted Leather (5), Obsidian Grinding Stone (6), Obsidian Idol (3), Idol of Rebirth (2)" }
entries[234227] = { ["name"] = "Plans: Obsidian Sageblade", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresMaster Swordsmith\nUse: Teaches you how to make Obsidian Sageblade.\nObsidian Sageblade\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)\nMain Hand Sword\n37 - 88 Damage Speed 1.50\n(41.67 damage per second)\n+14 Stamina\n+12 Intellect\nDurability 105 / 105\nRequires Level 60\nEquip: Increases damage and healing done by magical spells and effects by up to 60.\nEquip: Decreases the magical resistances of your spell targets by 20.\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)\nRequires Arcanite Bar (30), Obsidian-Infused Thorium Bar (8), Nexus Crystal (3), Obsidian Grinding Stone (3), Obsidian Idol (3), Idol of the Sage (2)" }
entries[234228] = { ["name"] = "Plans: Obsidian Defender", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresMaster Axesmith\nUse: Teaches you how to make Obsidian Defender.\nObsidian Defender\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)\nMain Hand Axe\n106 - 198 Damage Speed 2.70\n(56.30 damage per second)\n+11 Stamina\nDurability 105 / 105\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Increased Defense +9.\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)\nRequires Arcanite Bar (30), Obsidian-Infused Thorium Bar (8), Obsidian Grinding Stone (6), Vermillion Idol (3), Obsidian Idol (3), Idol of the Sun (2)" }
entries[234235] = { ["name"] = "Pattern: Glowing Chitin Armor Kit", ["text"] = "Binds when picked up\nRequires Leatherworking (300)\nRequires Elemental Leatherworking\nUse: Teaches you how to craft a Glowing Chitin Armor Kit.\nGlowing Chitin Armor Kit\nRequires Level 50\nUse: Permanently increase the spell damage and healing of an item worn on the chest, legs, hands or feet by up to 10. Only usable on items level 45 and above.\nRequires Spiked Silithid Chitin (5), Mooncloth (3), Core Armor Kit" }
entries[234236] = { ["name"] = "Pattern: Sharpened Chitin Armor Kit", ["text"] = "Binds when picked up\nRequires Leatherworking (300)\nRequires Dragonscale Leatherworking\nUse: Teaches you how to craft a Sharpened Chitin Armor Kit.\nSharpened Chitin Armor Kit\nRequires Level 50\nUse: Permanently cause an item worn on the chest, legs, hands or feet to cause 20 Nature damage to the attacker when struck in combat. Only usable on items level 45 and above.\nRequires Spiked Silithid Chitin (5), Cured Rugged Hide (3), Core Armor Kit" }
