entries[234251] = { ["name"] = "Pattern: Qiraji Silk Drape", ["text"] = "Binds when picked up\nRequires Tailoring (300)\nUse: Teaches you how to sew a Qiraji Silk Drape.\nQiraji Silk Drape\nBinds when equipped\nBack\n56 Armor\n+7 Stamina\n+10 Intellect\n+8 Spirit\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases healing done by up to 31 and damage done by up to 11 for all magical spells and effects.\nRequires Bolt of Qiraji Silk (9), Spiked Silithid Chitin (8), Cured Rugged Hide (4), Enchanted Leather (8), Rune Thread" }
entries[234252] = { ["name"] = "Recipe: Flask of Unyielding Sorrow", ["text"] = "Binds when picked up\nRequires Alchemy (300)\nUse: Teaches you how to make a Flask of Unyielding Sorrow.\nFlask of Unyielding Sorrow\nRequires Level 60\nUse: Increases healing done by magical spells and effects by up to 80, damage done by magical spells and effects by up to 27, and mana regeneration by 12 mana per 5 seconds for 2 hrs. You can only have the effect of one flask at a time. This effect persists through death. (3 Sec Cooldown)\nRequires Greater Eternal Essence , Hive Thistle , Flask of Distilled Wisdom , Crystal Vial" }
entries[234253] = { ["name"] = "Recipe: Flask of Ancient Knowledge", ["text"] = "Binds when picked up\nRequires Alchemy (300)\nUse: Teaches you how to make a Flask of Ancient Knowledge.\nFlask of Ancient Knowledge\nRequires Level 60\nUse: Increases damage done by magical spells and effects by up to 180 for 2 hrs. You can only have the effect of one flask at a time. This effect persists through death. (3 Sec Cooldown)\nRequires Greater Eternal Essence , Qiraji Stalker Venom , Flask of Supreme Power , Crystal Vial" }
