entries[234256] = { ["name"] = "Recipe: Flask of Madness", ["text"] = "Binds when picked up\nRequires Alchemy (300)\nUse: Teaches you how to make a Flask of Madness.\nFlask of Madness\nRequires Level 60\nUse: Increases attack power by 50 for 2 hrs. You can only have the effect of one flask at a time. This effect persists through death. (3 Sec Cooldown)\nRequires Greater Eternal Essence , Ancient Sandworm Bile , Flask of Chromatic Resistance , Crystal Vial" }
entries[234257] = { ["name"] = "Recipe: Elixir of the Honey Badger", ["text"] = "Binds when picked up\nRequires Alchemy (300)\nRequiresCenarion Circle\n- Honored\nUse: Teaches you how to make an Elixir of the Honey Badger.\nElixir of the Honey Badger\nRequires Level 60\nUse: Increases Agility by 30, chance to get a critical hit by 2%, and Nature Resistance by 15 for 1 hour. (3 Sec Cooldown)\nRequires Mountain Silversage (2), Hive Thistle (2), Qiraji Stalker Venom , Crystal Vial" }
entries[234258] = { ["name"] = "Recipe: Elixir of the Mage-Lord", ["text"] = "Binds when picked up\nRequires Alchemy (300)\nRequiresCenarion Circle\n- Honored\nUse: Teaches you how to make an Elixir of the Mage-Lord.\nElixir of the Mage-Lord\nRequires Level 60\nUse: Increases spell damage by up to 40 and Nature Resistance by 15 for 1 hour. (3 Sec Cooldown)\nRequires Plaguebloom (2), Hive Thistle (2), Qiraji Stalker Venom , Crystal Vial" }
entries[234259] = { ["name"] = "Recipe: Elixir of the Ironside", ["text"] = "Binds when picked up\nRequires Alchemy (300)\nRequiresCenarion Circle\n- Honored\nUse: Teaches you how to make an Elixir of the Ironside.\nElixir of the Ironside\nRequires Level 60\nUse: Increases armor by 450, defense value by 5, and Nature Resistance by 15 for 1 hour. (3 Sec Cooldown)\nRequires Icecap (2), Hive Thistle (2), Qiraji Stalker Venom , Crystal Vial" }
entries[234260] = { ["name"] = "Recipe: Elixir of Alacrity", ["text"] = "Binds when picked up\nRequires Alchemy (300)\nRequiresCenarion Circle\n- Friendly\nUse: Teaches you how to make an Elixir of Alacrity.\nElixir of Alacrity\nRequires Level 60\nUse: Increases the player's run speed by 15% for 1 hour. (3 Sec Cooldown)\nRequires Dreamfoil (2), Hive Thistle (2), Qiraji Stalker Venom , Crystal Vial" }
entries[234261] = { ["name"] = "Schematic: Arcane Megabomb", ["text"] = "Binds when picked up\nRequires Engineering (300)\nRequiresCenarion Circle\n- Revered\nUse: Teaches you how to make an Arcane Megabomb.\nArcane Megabomb\nRequires Level 60\nUse: Drains 1075 to 1525 mana from those in the blast radius and does 50% of the mana drained in damage to the target. Also Silences targets in the blast for 5 sec. (1 Min Cooldown)\nRequires Delicate Arcanite Converter , Nexus Crystal , Runecloth" }
entries[234262] = { ["name"] = "Schematic: The Fumigator", ["text"] = "Binds when picked up\nRequires Engineering (300)\nRequiresCenarion Circle\n- Honored\nUse: Teaches you how to make The Fumigator.\nThe Fumigator\nRequires Level 60\nUse: Explodes when triggered dealing 650 to 950 Fire damage to all enemies nearby and 475 to 725 damage to you. Deals extra damage to Silithid creatures in Silithus. (5 Min Cooldown)\nRequires Qiraji Stalker Venom , Obsidian Blasting Powder (2), Runecloth" }
entries[234263] = { ["name"] = "Schematic: Obsidian Bomb", ["text"] = "Binds when picked up\nRequires Engineering (300)\nRequiresCenarion Circle\n- Friendly\nUse: Teaches you how to make an Obsidian Bomb.\nObsidian Bomb\nRequires Level 60\nUse: Inflicts 530 to 670 Fire damage in a 5 yard radius. (1 Min Cooldown)\nRequires Obsidian Blasting Powder (3), Spiked Silithid Chitin , Qiraji Silk , Dense Stone" }
entries[234264] = { ["name"] = "Schematic: G00 DV-1B3 Generator", ["text"] = "Binds when picked up\nRequires Engineering (300)\nUse: Teaches you how to make a Good Vibe Generator.\n\nG00 DV-1B3 Generator\nBinds when picked up\nUnique\nRequires Level 60\nUse: Unfolds into a G00 DV-1B3 Generator that can repair damaged items and purchase unwanted goods. After 10 min its internal motor fails and it must recover. (4 Hrs Cooldown)\nRequires Obsidian Blasting Powder (20), Hive Thistle (30), Bolt of Qiraji Silk (8), Qiraji Stalker Venom (8), Ancient Sandworm Bile (8), Spiked Silithid Chitin (8)" }
entries[234265] = { ["name"] = "Schematic: Tuned Force Reactive Disk", ["text"] = "Binds when picked up\nRequires Engineering (300)\nUse: Teaches you how to make a Tuned Force Reactive Disk.\n\nTuned Force Reactive Disk\nBinds when equipped\nOff Hand Shield\n2822 Armor\n52 Block\n+20 Stamina\nDurability 120 / 120\nRequires Level 60\nEquip: Increased Defense +7.\nEquip: When the shield blocks it releases an electrical charge that damages all nearby enemies. (1s cooldown)\nUse: Charge up the energy within the shield for 3 sec to deal 450 to 750 Nature damage to all nearby enemies. After use, the shield needs 10 sec to recharge. (2 Min Cooldown)\nRequires Force Reactive Disk , Spiked Silithid Chitin (4), Obsidian-Infused Thorium Bar (8), Obsidian Blasting Powder (5)" }
entries[234266] = { ["name"] = "Formula: Speedstone", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nUse: Teaches you how to create a Speedstone.\nSpeedstone\nBinds when equipped\nUnique-Equipped\nTrinket\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 2%.\nEquip: Increases your attack speed by 2%.\nRequires Monstrous Silithid Chitin (10), Ancient Sandworm Bile (10), Nexus Crystal (6), Obsidian Grinding Stone (6), Swiftthistle (20)" }
entries[234267] = { ["name"] = "Formula: Tear of the Dreamer", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nUse: Teaches you how to create a Tear of the Dreamer.\nTear of the Dreamer\nBinds when equipped\nUnique-Equipped: Crystallized Tear (1)\nTrinket\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Increases damage and healing done by magical spells and effects by up to 46.\nRequires Monstrous Silithid Chitin (10), Ancient Sandworm Bile (10), Nexus Crystal (4), Obsidian-Infused Thorium Bar (10), Hive Thistle (10)" }
entries[234268] = { ["name"] = "Formula: Lodestone of Retaliation", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nUse: Teaches you how to create a Lodestone of Retaliation.\nLodestone of Retaliation\nBinds when equipped\nUnique-Equipped\nTrinket\n+23 Stamina\nRequires Level 60\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%.\nEquip: Increased Defense +11.\nEquip: When struck in combat inflicts 80 Nature damage to the attacker. Causes twice as much threat as damage dealt.\nRequires Spiked Silithid Chitin (10), Ancient Sandworm Bile (5), Nexus Crystal (4), Obsidian-Infused Thorium Bar (10), Qiraji Stalker Venom (10)" }
entries[234269] = { ["name"] = "Formula: Enchanted Stopwatch", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nUse: Teaches you how to create a Enchanted Stopwatch.\nEnchanted Stopwatch\nBinds when equipped\nUnique-Equipped\nTrinket\nRequires Level 60\nUse: Increases run speed by 40% for 10 sec. (2 Min Cooldown)\nRequires Obsidian-Infused Thorium Bar (3), Obsidian Blasting Powder (6), Large Brilliant Shard (4), Swiftness Potion (3)" }
entries[234270] = { ["name"] = "Formula: Ruby-Encrusted Broach", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nUse: Teaches you how to create a Ruby-Encrusted Broach.\nRuby-Encrusted Broach\nBinds when equipped\nUnique-Equipped: Jeweled Healing Focus (1)\nTrinket\n+18 Intellect\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases healing done by up to 68 and damage done by up to 23 for all magical spells and effects.\nRequires Spiked Silithid Chitin (10), Ancient Sandworm Bile (5), Nexus Crystal (6), Obsidian-Infused Thorium Bar (10), Hive Thistle (10), Qiraji Stalker Venom (10)" }
entries[234271] = { ["name"] = "Formula: Scroll: Wrath of the Swarm", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nRequiresCenarion Circle\n- Friendly\nUse: Teaches you how to conjure a Scroll: Wrath of the Swarm.\nScroll: Wrath of the Swarm\nBinds when picked up\nRequires Level 60\nRequires Enchanting (300)\nUse: Read from the scroll, evoking the Wrath of the Swarm, empowering your raid to deal up to 40 increased damage and healing with spells, and increasing attack power by 40 for 1 hour. (1 Min Cooldown)\nRequires Greater Eternal Essence , Runecloth" }
entries[234272] = { ["name"] = "Formula: Enchanted Repellent", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nRequiresCenarion Circle\n- Friendly\nUse: Teaches you how to create Enchanted Repellent.\nEnchanted Repellent\nRequires Level 60\nUse: While applied to target weapon or shield it increases spell damage by up to 45 and increases Spell Critical chance by 1% . Lasts for 30 minutes.\n5 Charges\nRequires Qiraji Stalker Venom (3), Hive Thistle (3), Illusion Dust (2)" }
entries[234275] = { ["name"] = "Formula: Enchanted Prayer Tome", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nUse: Teaches you how to create an Enchanted Prayer Tome.\nEnchanted Prayer Tome\nBinds when equipped\nRelic Libram\nRequires Level 60\nEquip: Increases the amount healed by your Holy Light and Flash of Light spells by 3%.\nRequires Nexus Crystal (3), Qiraji Silk (10), Obsidian-Infused Thorium Bar (2), Enchanted Leather (4)" }
entries[234276] = { ["name"] = "Formula: Enchanted Totem", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nUse: Teaches you how to create an Enchanted Totem.\nEnchanted Totem\nBinds when equipped\nRelic Totem\nRequires Level 60\nEquip: Increases the amount healed by your Chain Heal and Healing Wave spells by 3%.\nRequires Nexus Crystal (3), Hive Thistle (10), Obsidian-Infused Thorium Bar (2), Enchanted Leather (3)" }
entries[234277] = { ["name"] = "Formula: Enchanted Mushroom", ["text"] = "Binds when picked up\nRequires Enchanting (300)\nUse: Teaches you how to create an Enchanted Mushroom.\nEnchanted Mushroom\nBinds when equipped\nRelic Idol\nRequires Level 60\nEquip: Increases the amount healed by your Lifebloom, Nourish, and Wild Growth spells by 3%.\nRequires Nexus Crystal (2), Hive Thistle (20), Enchanted Leather (3), Qiraji Stalker Venom (4), Ancient Sandworm Bile (4)" }
