entries[234428] = { ["name"] = "Obsidian Heartseeker", ["text"] = "Binds when equipped\nUnique-Equipped: Obsidian Weapon (1)\nOne-Hand Dagger\n67 - 125 Damage Speed 1.70\n(56.47 damage per second)\n+11 Strength\n+10 Stamina\nDurability 65 / 65\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)" }
entries[234429] = { ["name"] = "Plans: Obsidian Heartseeker", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresWeaponsmith\nUse: Teaches you how to make Obsidian Heartseeker.\nObsidian Heartseeker\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)\nOne-Hand Dagger\n67 - 125 Damage Speed 1.70\n(56.47 damage per second)\n+11 Strength\n+10 Stamina\nDurability 65 / 65\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)\nRequires Arcanite Bar (30), Obsidian-Infused Thorium Bar (8), Obsidian Grinding Stone (6), Obsidian Idol (3), Onyx Idol (3), Idol of Death (2)" }
entries[234434] = { ["name"] = "Obsidian Shotgun", ["text"] = "Binds when equipped\nUnique-Equipped: Obsidian Weapon (1)\nRanged Gun\n101 - 189 Damage Speed 3.30\n(43.94 damage per second)\n+9 Stamina\nDurability 90 / 90\nRequires Level 60\nEquip: +31 ranged Attack Power.\nEquip: Chance on ranged hit to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)" }
entries[234435] = { ["name"] = "Schematic: Obsidian Shotgun", ["text"] = "Binds when picked up\nRequires Engineering (300)\nUse: Teaches you how to make an Obsidian Shotgun.\nObsidian Shotgun\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)\nRanged Gun\n101 - 189 Damage Speed 3.30\n(43.94 damage per second)\n+9 Stamina\nDurability 90 / 90\nRequires Level 60\nEquip: +31 ranged Attack Power.\nEquip: Chance on ranged hit to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)\nRequires Arcanite Bar (30), Obsidian-Infused Thorium Bar (8), Nexus Crystal (3), Lambent Idol (3), Jasper Idol (3), Idol of Strife (2)" }
entries[234436] = { ["name"] = "Signet Ring of the Bronze Dragonflight", ["text"] = "Binds when picked up\nUnique-Equipped: Signet Ring of the Bronze Dragonflight (1)\nFinger\n+8 Stamina\n+9 Intellect\nClasses: Priest , Warlock , Druid\nRequires Level 60\nRequiresBrood of Nozdormu\n- Exalted\nEquip: Increases damage and healing done by magical spells and effects by up to 30.\nEquip: Increases the damage dealt by all of your damage over time spells by 3% per piece of Timeworn armor equipped.\n\"The Path of the Subjugator\"" }
