entries[234444] = { ["name"] = "Occult Poison II", ["text"] = "Classes: Rogue\nRequires Level 60\nUse: Coats a weapon with poison that lasts for 30 minutes. Each strike has a 30% chance of poisoning the enemy for 136 Nature damage over 12 sec and causing the enemy to take 4% increased Arcane, Fire, Frost, Nature, and Shadow damage. Stacks up to 5 times on a single target.\n\nOccult Poison counts as Deadly Poison and benefits from all talents and effects that trigger from or modify Deadly Poison. (Proc chance: 30%)" }
