entries[234447] = { ["name"] = "Bubbles' Rod of Transformation", ["text"] = "Binds when picked up\nUnique\nUse: Transforms you into a Furbolg for 5 min. (15 Min Cooldown)" }
entries[234458] = { ["name"] = "Plans: Jagged Obsidian Shield", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresCenarion Circle\n- Revered\nUse: Teaches you how to make a Jagged Obsidian Shield.\nJagged Obsidian Shield\nBinds when equipped\nOff Hand Shield\n2822 Armor\n52 Block\n+12 Stamina\nDurability 120 / 120\nRequires Level 60\nEquip: Increases your chance to block attacks with a shield by 2%.\nEquip: Increases the block value of your shield by 14.\nEquip: When struck by a harmful spell, the caster of that spell has a 20% chance to be silenced for 3 sec. (Proc chance: 20%, 20s cooldown)\nRequires Large Obsidian Shard (8), Small Obsidian Shard (24), Enchanted Thorium Bar (8), Essence of Earth (4)" }
