entries[235497] = { ["name"] = "Draught of the Sands", ["text"] = "Binds when picked up\nClasses: Hunter\nRequires Level 55\nUse: Increases all damage caused against targets in Silithus, Ahn'Qiraj, Eastern Plaguelands, and Naxxramas by 3% and increases critical damage caused against targets in these areas by an additional 3%. (3 Sec Cooldown)" }
entries[235511] = { ["name"] = "Flawless Yellow Qiraji Resonating Crystal", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 60\nUse: Summons and dismisses a rideable Qiraji battle tank. This is a very fast mount. (3 Sec Cooldown)" }
