entries[235825] = { ["name"] = "Draught of the Sands", ["text"] = "Binds when picked up\nClasses: Rogue\nRequires Level 55\nUse: Increases all damage caused against targets in Silithus, Ahn'Qiraj, Eastern Plaguelands, and Naxxramas by 2% and increases critical damage caused against targets in these areas by an additional 2%. (3 Sec Cooldown)" }
entries[235852] = { ["name"] = "Violet Satchel", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"This small satchel bears the mark of the Kirin Tor of Dalaran. It seems to contain a few small objects but curiously, you find that you are unable to open the flap to see what is inside.\"" }
entries[235867] = { ["name"] = "Scrap of Parchment", ["text"] = "Binds when picked up\nUnique\n\"The scrap of parchment appears to have been torn off of a larger poster or flyer. The only words legible on it seem to be a name ...Archmage Tarsis Kir-Moldir\"" }
