entries[235888] = { ["name"] = "Clobberclub", ["text"] = "Binds when picked up\nOne-Hand Mace\n171 - 209 Damage Speed 2.80\n(67.86 damage per second)\n+10 Stamina\nDurability 105 / 105\nRequires Level 60\nEquip: Increased Maces +3.\nEquip: Increased Defense +10.\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%." }
