entries[235890] = { ["name"] = "Shadow Weaver's Needle", ["text"] = "Binds when picked up\nMain Hand Dagger\n36 - 104 Damage Speed 1.70\n(41.18 damage per second)\n+11 Stamina\n+17 Intellect\nDurability 75 / 75\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Increases damage and healing done by magical spells and effects by up to 96." }
entries[235891] = { ["name"] = "Ol' Reliable", ["text"] = "Binds when picked up\nTwo-Hand Mace\n290 - 355 Damage Speed 3.80\n(84.87 damage per second)\n+50 Strength\n+12 Stamina\nDurability 120 / 120\nRequires Level 60\nUse: Smash the corpse of a fallen friend or foe, dealing 588 damage to nearby enemies. (2 Min Cooldown)\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\"Guarantees that no grave needs to be dug twice.\"" }
