entries[235893] = { ["name"] = "Shadowbound Grimoire", ["text"] = "Binds when picked up\nHeld In Off-hand\n+11 Intellect\nRequires Level 60\nEquip: Increases damage done by Shadow spells and effects by up to 43.\n\nKharon's Decree (0/2)\nShadowbound Grimoire\nDoomsayer's Demise\n(2) Set : The damage dealt by Creeping Darkness is increased by 100%." }
entries[235894] = { ["name"] = "Doomsayer's Demise", ["text"] = "Binds when picked up\nRanged Wand\n153 - 188 Shadow Damage Speed 1.50\n(113.67 damage per second)\nDurability 75 / 75\nRequires Level 60\nEquip: Periodic shadow effects have a chance to apply Creeping Darkness up to 5 times. Spells which deal direct Shadow damage detonate this effect, dealing 100 damage per stack. (1.5s cooldown)\n\nKharon's Decree (0/2)\nShadowbound Grimoire\nDoomsayer's Demise\n(2) Set : The damage dealt by Creeping Darkness is increased by 100%." }
entries[236002] = { ["name"] = "List of Components", ["text"] = "Binds when picked up\n<Right Click to Read>" }
entries[236005] = { ["name"] = "Dreadnaught Breastplate", ["text"] = "Sanctified\nBinds when picked up\nChest Plate\n1027 Armor\n+21 Strength\n+42 Stamina\nDurability 165 / 165\nClasses: Warrior\nRequires Level 60\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%.\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Increases your attack speed by 1%.\nEquip: Increased Defense +20.\n\nDreadnaught's Battlegear (0/9)\nDreadnaught Helmet\nDreadnaught Pauldrons\nDreadnaught Breastplate\nDreadnaught Waistguard\nDreadnaught Legplates\nDreadnaught Sabatons\nDreadnaught Bracers\nDreadnaught Gauntlets\nRing of the Dreadnaught\n(2) Set : Your Taunt ability never misses, and your chance to be Dodged or Parried is reduced by 2%.\n(4) Set : Reduces the cooldown on your Shield Wall ability by 3 min and reduces the cooldown on your Recklessness ability by 3 min. Recklessness can now be used in any Stance and does not increase damage taken.\n(6) Set : When you take damage from an Undead enemy, the remaining duration of your active Last Stand is reset to 20 sec." }
entries[236006] = { ["name"] = "Dreadnaught Legplates", ["text"] = "Sanctified\nBinds when picked up\nLegs Plate\n861 Armor\n+26 Strength\n+37 Stamina\nDurability 120 / 120\nClasses: Warrior\nRequires Level 60\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%.\nEquip: Increases your attack speed by 1%.\nEquip: Increased Defense +17.\n\nDreadnaught's Battlegear (0/9)\nDreadnaught Helmet\nDreadnaught Pauldrons\nDreadnaught Breastplate\nDreadnaught Waistguard\nDreadnaught Legplates\nDreadnaught Sabatons\nDreadnaught Bracers\nDreadnaught Gauntlets\nRing of the Dreadnaught\n(2) Set : Your Taunt ability never misses, and your chance to be Dodged or Parried is reduced by 2%.\n(4) Set : Reduces the cooldown on your Shield Wall ability by 3 min and reduces the cooldown on your Recklessness ability by 3 min. Recklessness can now be used in any Stance and does not increase damage taken.\n(6) Set : When you take damage from an Undead enemy, the remaining duration of your active Last Stand is reset to 20 sec." }
entries[236007] = { ["name"] = "Dreadnaught Helmet", ["text"] = "Sanctified\nBinds when picked up\nHead Plate\n800 Armor\n+27 Strength\n+40 Stamina\nDurability 100 / 100\nClasses: Warrior\nRequires Level 60\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%.\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Increases your attack speed by 1%.\nEquip: Increased Defense +14.\n\nDreadnaught's Battlegear (0/9)\nDreadnaught Helmet\nDreadnaught Pauldrons\nDreadnaught Breastplate\nDreadnaught Waistguard\nDreadnaught Legplates\nDreadnaught Sabatons\nDreadnaught Bracers\nDreadnaught Gauntlets\nRing of the Dreadnaught\n(2) Set : Your Taunt ability never misses, and your chance to be Dodged or Parried is reduced by 2%.\n(4) Set : Reduces the cooldown on your Shield Wall ability by 3 min and reduces the cooldown on your Recklessness ability by 3 min. Recklessness can now be used in any Stance and does not increase damage taken.\n(6) Set : When you take damage from an Undead enemy, the remaining duration of your active Last Stand is reset to 20 sec." }
