entries[236022] = { ["name"] = "Band of the Dreadnaught", ["text"] = "Sanctified\nBinds when picked up\nUnique-Equipped: Desecrated Ring (1)\nFinger\n+25 Strength\nClasses: Warrior\nRequires Level 60\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%.\nEquip: Gives you a 2% chance to get an extra attack on the same target after dealing damage with your weapon. (Proc chance: 2%, 200ms cooldown)\n\nDreadnaught's Warplate (0/9)\nDreadnaught Horns\nDreadnaught Shoulders\nDreadnaught Cuirass\nDreadnaught Belt\nDreadnaught Tassets\nDreadnaught Greaves\nDreadnaught Wrists\nDreadnaught Grips\nBand of the Dreadnaught\n(2) Set : Increases damage done by your Deep Wounds talent by 20%.\n(4) Set : Reduces the cooldown on your Bloodthirst, Mortal Strike, and Shield Slam abilities by 25%.\n(6) Set : Your melee critical strikes against Undead enemies grant you 2% increased damage and critical damage done to Undead for 30 sec, stacking up to 9 times." }
entries[236023] = { ["name"] = "Bonescythe Breastplate", ["text"] = "Sanctified\nBinds when picked up\nChest Leather\n262 Armor\n+30 Strength\n+46 Agility\n+12 Stamina\nDurability 120 / 120\nClasses: Rogue\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%.\nEquip: Increases your attack speed by 1%.\n\nBonescythe Armor (0/9)\nBonescythe Helmet\nBonescythe Pauldrons\nBonescythe Breastplate\nBonescythe Waistguard\nBonescythe Legplates\nBonescythe Sabatons\nBonescythe Bracers\nBonescythe Gauntlets\nBonescythe Ring\n(2) Set : Your Ambush, and Instant Poison deal 20% more damage. Your Backstab deals 10% more damage (Does not benefit Mutilate). You heal for 5% of all damage done by your Poisons.\n(4) Set : You have a 100% chance to gain 1 Energy each time you deal periodic Nature or Bleed damage.\n(6) Set : You gain 3% increased damage and critical damage done to Undead for 30 sec per Combo Point you spend, stacking up to 6 times." }
