entries[236076] = { ["name"] = "Plagueheart Garb", ["text"] = "Sanctified\nBinds when picked up\nChest Cloth\n238 Armor\n+42 Stamina\n+10 Intellect\n+10 Spirit\nDurability 100 / 100\nClasses: Warlock\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases damage and healing done by magical spells and effects by up to 16.\nEquip: Increased Defense +15.\n\nPlagueheart Stitchings (0/9)\nPlagueheart Crown\nPlagueheart Mantle\nPlagueheart Waistguard\nPlagueheart Pants\nPlagueheart Boots\nPlagueheart Wristguards\nPlagueheart Handguards\nPlagueheart Garb\nPlagueheart Loop\n(2) Set : Your Menace ability never misses, and your chance to be Dodged or Parried or for your spells to miss is reduced by 2%.\n(4) Set : Reduces the cooldown on your Infernal Armor ability by 10 sec and reduces the cooldown on your Demonic Grace ability by 3 sec.\n(6) Set : When an Undead enemy attempts to attack you, the remaining duration of your active Vengeance is reset to 20 sec." }
entries[236077] = { ["name"] = "Frostfire Bindings", ["text"] = "Sanctified\nBinds when picked up\nWrist Cloth\n58 Armor\n+10 Stamina\n+12 Intellect\nDurability 35 / 35\nClasses: Mage\nRequires Level 60\nEquip: Increases your casting speed by 1%.\nEquip: Increases damage and healing done by magical spells and effects by up to 30.\n\nFrostfire Regalia (0/9)\nFrostfire Circlet\nFrostfire Shoulderpads\nFrostfire Belt\nFrostfire Leggings\nFrostfire Sandals\nFrostfire Bindings\nFrostfire Gloves\nFrostfire Robe\nFrostfire Ring\n(2) Set : Reduces the cooldown on your Evocation ability by 80%.\n(4) Set : Your Evocation grants you 1% increased damage done every sec you channel it, stacking up to 8 times and lasting 45 sec.\n(6) Set : Your Ignite damage does not decay on Undead targets below 20% health, and Undead targets below 20% health take damage as if they were Frozen." }
