entries[236179] = { ["name"] = "Earthshatter Armor", ["text"] = "Sanctified\nBinds when picked up\nChest Mail\n576 Armor\n+44 Strength\n+10 Stamina\n+10 Intellect\nDurability 140 / 140\nClasses: Shaman\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Improves your chance to get a critical strike with all spells and attacks by 2%.\nEquip: Increases your attack speed by 2%.\n\nThe Earthshatterer's Rage (0/9)\nEarthshatter Helmet\nEarthshatter Epaulets\nEarthshatter Armor\nEarthshatter Belt\nEarthshatter Leggings\nEarthshatter Treads\nEarthshatter Vambraces\nEarthshatter Grips\nSignet of the Earthshatterer\n(2) Set : While Static Shock is engraved, the damage done by your Lightning Shield is increased by 100%.\n(4) Set : Reduces the cooldown on your Lava Lash and Stormstrike abilities by 1.5 sec.\n(6) Set : You gain 3% increased damage and critical damage done to Undead for 30 sec for each charge of Maelstrom Weapon you earn, stacking up to 7 times." }
entries[236182] = { ["name"] = "Dreamwalker Headpiece", ["text"] = "Sanctified\nBinds when picked up\nHead Leather\n205 Armor\n+11 Stamina\n+11 Intellect\n+11 Spirit\nDurability 70 / 70\nClasses: Druid\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 2%.\nEquip: Increases healing done by up to 97 and damage done by up to 32 for all magical spells and effects.\n\nDreamwalker Raiment (0/9)\nDreamwalker Headpiece\nDreamwalker Spaulders\nDreamwalker Tunic\nDreamwalker Girdle\nDreamwalker Legguards\nDreamwalker Boots\nDreamwalker Wristguards\nDreamwalker Handguards\nRing of the Dreamwalker\n(2) Set : Your Lifebloom now has a 100% chance to heal the target for one application of its dispel amount each time the target takes damage. This effect can only occur once every few seconds.\n(4) Set : Each time your Rejuvenation rank 10 or rank 11 heals a target, you have a 25% chance to restore 60 mana, 8 energy, or 2 rage to your target.\n(6) Set : Your Rejuvenation and Regrowth refresh their duration to full each time their target is damaged by an Undead enemy." }
